let DB;function load(){try{DB=JSON.parse(localStorage.pq7)}catch(e){}if(!DB||DB.v!==7){DB=seed();save()}}
function save(){try{localStorage.pq7=JSON.stringify(DB)}catch(e){}}
load();

/* ---------- cambios, auditoría y deshacer ---------- */
let UNDO=null;
function commit(msg,fn,au,opts){const snap=JSON.stringify(DB);const r=fn();if(au)DB.audit.unshift({id:nid('au'),t:HOY+' '+now(),u:DB.me.nombre,acc:au.acc,ent:au.ent,obj:au.obj,antes:au.antes||null,despues:au.despues||null,ip:'192.168.1.20'});save();UNDO=snap;if(!(opts&&opts.keep))cerrar();rerender();toast(msg,1,opts&&opts.extra);return r}
function undo(){if(!UNDO)return;DB=JSON.parse(UNDO);UNDO=null;save();cerrar();rerender();toast('Se deshizo la última acción. Los datos volvieron a como estaban.')}
function hist(r,acc,c){(r.h=r.h||[]).unshift({t:HOY+' '+now(),u:DB.me.nombre,acc,c:c||[]})}

/* ---------- registro de entidades ---------- */
const E={};
const col=(l,k,o)=>Object.assign({l,k},o||{});

/* ---------- tabla genérica ---------- */
const T={};
function table(id,cfg){if(!T[id])T[id]={q:'',chip:0,sort:null,dir:1,page:0,sel:new Set(),per:10,loaded:false};Object.assign(T[id],cfg);return `<div class="pn" id="t-${id}">${tb(id)}</div>`}
function skel(n){return `<div class="fb"><span class="skl" style="width:14rem;height:1.6rem"></span><span class="skl" style="width:10rem;height:1.6rem;margin-left:auto"></span></div><div aria-busy="true" aria-label="Cargando">${Array.from({length:6},()=>`<div class="li" style="padding:.9rem 1rem">${Array.from({length:Math.min(n,5)},(x,i)=>`<span class="skl" style="flex:${i?1:2}"></span>`).join('')}</div>`).join('')}</div>`}
function errState(retry){return `<div class="empty er" role="alert">${I('warn')}<h3>No se pudieron cargar los datos</h3><p>Parece que se perdió la conexión con el servidor de la parroquia. Sus datos están a salvo. Revise su internet e intente de nuevo.</p><button class="btn p" onclick="DB.prefs.err=0;save();${retry}">${I('refresh')}Reintentar</button></div>`}
function emptyState(t,p,btn){return `<div class="empty">${I('list')}<h3>${t}</h3><p>${p}</p>${btn||''}</div>`}
function tb(id){const t=T[id];
 if(DB.prefs.err)return errState(`T['${id}'].loaded=false;rt('${id}')`);
 if(!t.loaded){setTimeout(()=>{t.loaded=true;if($('#t-'+id))rt(id)},420);return skel(t.cols.length)}
 let rows=t.rows();const all=rows.length;
 if(t.chip&&t.chips)rows=rows.filter(t.chips[t.chip][1]);
 if(t.fx)rows=rows.filter(t.fx);
 if(t.q){const q=norm(t.q);rows=rows.filter(r=>norm(t.cols.map(c=>c.s?c.s(r):r[c.k]).join(' ')).includes(q))}
 if(t.sort!=null){const c=t.cols[t.sort];const g=c.s||(r=>r[c.k]);rows=[...rows].sort((a,b)=>{let x=g(a),y=g(b);if(c.d){x=iso(x);y=iso(y)}if(typeof x=='number'&&typeof y=='number')return (x-y)*t.dir;return String(x??'').localeCompare(String(y??''),'es',{numeric:true})*t.dir})}
 const n=rows.length,pgs=Math.max(1,Math.ceil(n/t.per));t.page=Math.min(t.page,pgs-1);const vis=rows.slice(t.page*t.per,t.page*t.per+t.per);
 const sel=t.bulk?1:0;const T_=`T['${id}']`;
 const head=`<div class="bulk ${t.sel.size?'on':''}"><b>${t.sel.size} seleccionados</b>${(t.bulk||[]).map((b,i)=>`<button class="btn" onclick="${T_}.bulk[${i}][1]([...${T_}.sel])">${b[0]}</button>`).join('')}<button class="btn" style="margin-left:auto" onclick="${T_}.sel.clear();rt('${id}')">${I('x')}Quitar selección</button></div>
 <div class="fb">${t.chips?I('flt')+t.chips.map((c,i)=>`<button class="chip ${i==t.chip?'on':''}" aria-pressed="${i==t.chip}" onclick="${T_}.chip=${i};${T_}.page=0;rt('${id}')">${c[0]}</button>`).join(''):''}${t.extra||''}<label class="fs">${I('srch')}<input placeholder="${t.ph||'Buscar…'}" value="${esc(t.q)}" oninput="${T_}.q=this.value;${T_}.page=0;rt('${id}',1)" aria-label="${t.ph||'Buscar'}"></label></div>`;
 if(!all)return head+emptyState(t.empty?.[0]||'Todavía no hay registros',t.empty?.[1]||'Cuando registre el primero aparecerá aquí.',t.empty?.[2]);
 if(!n)return head+emptyState('No hay resultados',`Ningún registro coincide${t.q?' con «'+esc(t.q)+'»':''} y los filtros elegidos.`,`<button class="btn" onclick="${T_}.q='';${T_}.chip=0;rt('${id}')">${I('x')}Limpiar filtros</button>`);
 return head+`<div class="wrap-t"><table><thead><tr>${sel?`<th style="width:2.4rem"><input type="checkbox" aria-label="Seleccionar todos los visibles" onclick="${vis.map(r=>`${T_}.sel[this.checked?'add':'delete']('${r.id}');`).join('')}rt('${id}')" ${vis.every(r=>t.sel.has(r.id))?'checked':''}></th>`:''}${t.cols.map((c,i)=>c.ns?`<th class="${c.c||''}">${c.l}</th>`:`<th class="s ${t.sort==i?'on':''} ${c.c||''}" aria-sort="${t.sort==i?(t.dir>0?'ascending':'descending'):'none'}" onclick="srt('${id}',${i})" tabindex="0" onkeydown="if(event.key=='Enter')srt('${id}',${i})">${c.l}<span class="ar">${t.sort==i?(t.dir>0?'↑':'↓'):'↕'}</span></th>`).join('')}</tr></thead>
 <tbody>${vis.map(r=>`<tr class="r ${t.sel.has(r.id)?'sl':''}" tabindex="0" onkeydown="if(event.key=='Enter')this.click()" onclick="${t.open?t.open(r):`det('${t.ent||id}','${r.id}')`}">${sel?`<td onclick="event.stopPropagation()"><input type="checkbox" aria-label="Seleccionar" ${t.sel.has(r.id)?'checked':''} onclick="${T_}.sel[this.checked?'add':'delete']('${r.id}');rt('${id}')"></td>`:''}${t.cols.map((c,i)=>{const v=c.f?c.f(r):esc(r[c.k]);const cls=[c.c||'',c.key?'k':''].join(' ').trim();return `<td class="${cls}" data-l="${c.l}">${c.b||(i==0&&!c.nb)?`<b style="font-weight:600">${v}</b>`:v}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>
 <div class="pg"><span>${t.page*t.per+1}–${Math.min(n,t.page*t.per+t.per)} de ${n}${n<all?` (filtrados de ${all})`:''}</span><button class="btn" ${t.page?'':'disabled'} onclick="${T_}.page--;rt('${id}')">${I('left')}Anterior</button><span>Página ${t.page+1} de ${pgs}</span><button class="btn" ${t.page<pgs-1?'':'disabled'} onclick="${T_}.page++;rt('${id}')">Siguiente${I('right')}</button></div>`}
function rt(id,f){const e=$('#t-'+id);if(!e)return;e.innerHTML=tb(id);if(f){const i=e.querySelector('.fs input');i.focus();i.setSelectionRange(99,99)}}
function srt(id,c){const t=T[id];t.dir=t.sort==c?-t.dir:1;t.sort=c;rt(id)}

/* ---------- vistas genéricas ---------- */
function ph(t,s,ac){return `<div class="ph"><div><h1>${t}</h1>${s?`<p>${s}</p>`:''}</div><div class="ac">${ac||''}</div></div>`}
function lv(ent,o){const e=E[ent];o=o||{};
 const ac=(e.lacts?e.lacts():'')+`<button class="btn hm" onclick="exportar('${e.p}')">${I('dl')}Exportar</button><button class="btn hm" onclick="imprimirLista('${ent}')">${I('print')}Imprimir</button>`+(e.noNew?'':`<button class="btn p" onclick="${e.newFn||`abrirForm('${ent}')`}">${I('plus')}${e.nuevo||'Nuevo '+e.s}</button>`);
 return (o.noHead?'':ph(e.p,e.sub?e.sub():'',ac))+(e.banner?e.banner():'')+table(ent,{ent,rows:()=>DB[e.tbl||ent],cols:e.cols,chips:e.chips,ph:e.ph||'Buscar '+e.p.toLowerCase()+'…',bulk:e.bulk||[['Exportar',ids=>exportar(e.p+' ('+ids.length+')')]],extra:e.extra,empty:[`Todavía no hay ${e.p.toLowerCase()}`,e.emptyTxt||`Cuando registre ${e.art||'el'} primer${e.art=='la'?'a':'o'} ${e.s} aparecerá aquí.`,e.noNew?'':`<button class="btn p" onclick="${e.newFn||`abrirForm('${ent}')`}">${I('plus')}${e.nuevo||'Nuevo '+e.s}</button>`],open:e.open})}
function rec(ent,id){return DB[E[ent].tbl||ent].find(x=>x.id==id)}
let DET=null;
function det(ent,id,tab){const e=E[ent],r=rec(ent,id);if(!r){toast('Este registro ya no existe.');return}DET={ent,id,tab:tab||0};
 const tabs=[['Resumen',()=>`<dl>${e.f(r).filter(f=>!f.hide).map(f=>`<dt>${f.l}</dt><dd>${fv(f,r[f.k])||'<span class="muted">—</span>'}</dd>`).join('')}</dl>`+(e.extra2?e.extra2(r):'')],...(e.tabs?e.tabs(r):[]),['Historial',()=>histView(r)]];
 const ti=Math.min(DET.tab,tabs.length-1);
 $('#dr').innerHTML=`<div class="drh"><div><h2>${esc(e.title(r))}</h2><p>${e.status?sb(e.status(r))+' &nbsp;':''}${e.sub2?e.sub2(r):''}</p></div><button class="btn g" onclick="cerrar()">${I('x')}Cerrar</button></div>
 <div style="padding:0 1.2rem"><div class="tabs" role="tablist" style="margin:0">${tabs.map((x,i)=>`<button role="tab" aria-selected="${i==ti}" class="${i==ti?'on':''}" onclick="det('${ent}','${id}',${i})">${x[0]}</button>`).join('')}</div></div>
 <div class="drb">${e.warn?e.warn(r):''}${tabs[ti][1]()}</div>
 <div class="drf">${e.acts?e.acts(r):''}<button class="btn hm" onclick="imprimirReg('${ent}','${id}')">${I('print')}Imprimir</button>${e.noDel?'':`<button class="btn d" onclick="${e.del=='anular'?`anular('${ent}','${id}')`:`borrar('${ent}','${id}')`}">${I(e.del=='anular'?'ban':'trash')}${e.del=='anular'?'Anular':'Eliminar'}</button>`}${e.noEdit?'':`<button class="btn p" onclick="abrirForm('${ent}','${id}')">${I('edit')}Editar</button>`}</div>`;
 scr(true);$('#dr').classList.add('on');$('#md').classList.remove('on')}
function fv(f,v){if(f.t=='ref'){const x=DB[f.ref].find(x=>x.id==v);return x?esc(f.lab?f.lab(x):x.nombre):''}if(f.t=='money')return v===''||v==null?'':money(v);if(f.t=='check')return v?'Sí':'No';if(f.t=='checks')return esc((v||[]).join(', '));if(f.k=='estado')return sb(v);return esc(v)}
function histView(r){const h=r.h||[];if(!h.length)return emptyState('Sin cambios registrados','Aquí verá quién creó o modificó este registro y qué cambió.');
 return `<div class="tl">${h.map(x=>`<div class="ok"><b style="font-weight:600">${esc(x.acc)}</b> <small>· ${esc(x.u)} · ${esc(x.t)}</small>${x.c&&x.c.length?`<table style="margin-top:.3rem;font-size:.85rem"><tbody>${x.c.map(c=>`<tr><td class="muted">${esc(c[0])}</td><td><del>${esc(c[1])||'—'}</del></td><td>→ <ins>${esc(c[2])||'—'}</ins></td></tr>`).join('')}</tbody></table>`:''}</div>`).join('')}</div>`}

/* ---------- formularios con validación ---------- */
function vfield(f,v){v=String(v??'').trim();
 if(f.t=='check'||f.t=='checks')return f.req&&(!v||v=='[]')?`Marque al menos una opción en «${f.l}».`:'';
 if(f.req&&!v)return f.t=='sel'||f.t=='ref'?`Elija una opción en «${f.l}».`:`Este dato es obligatorio. Escriba ${f.art||'el dato'} «${f.l.toLowerCase()}».`;
 if(!v)return '';
 if(f.t=='dni'&&!/^\d{8}$/.test(v))return 'El DNI debe tener 8 números, sin puntos ni espacios.';
 if(f.t=='tel'&&!/^9\d{8}$/.test(v.replace(/\s/g,''))&&!/^0\d{6,8}$/.test(v))return 'El celular debe tener 9 números y empezar con 9. Ejemplo: 987654321.';
 if(f.t=='email'&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v))return 'El correo no parece válido. Debe tener @ y un dominio, por ejemplo nombre@correo.com.';
 if(f.t=='date'){if(!/^\d\d\/\d\d\/\d{4}$/.test(v))return 'Escriba la fecha como día/mes/año. Ejemplo: 05/03/2026.';const[d,m]=v.split('/').map(Number);if(m<1||m>12||d<1||d>31)return 'Esa fecha no existe. Revise el día y el mes.';if(f.past&&iso(v)>iso(HOY))return 'La fecha no puede ser posterior a hoy.';if(f.future&&iso(v)<iso(HOY))return 'La fecha no puede ser anterior a hoy.'}
 if(f.t=='time'&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))return 'Escriba la hora como 18:30 (formato de 24 horas).';
 if((f.t=='money'||f.t=='num')&&(!/^\d+([.,]\d{1,2})?$/.test(v.replace(/\s/g,''))))return 'Escriba solo números. Ejemplo: 25 o 25,50.';
 if(f.min!=null&&num(v)<f.min)return `El valor mínimo es ${f.min}.`;
 return ''}
function inp(f,v,errs){const id='f_'+f.k,er=errs&&errs[f.k],a=`id="${id}" name="${f.k}" ${er?'aria-invalid="true" aria-describedby="e_'+f.k+'"':''} ${f.ro?'readonly':''}`;let h;
 if(f.t=='sel'||f.t=='ref'){const o=f.t=='ref'?DB[f.ref].filter(f.fil||(()=>1)).map(x=>[x.id,f.lab?f.lab(x):x.nombre]):(typeof f.o=='function'?f.o():f.o).map(x=>[x,x]);h=`<select ${a}><option value="">Elija…</option>${o.map(x=>`<option value="${esc(x[0])}" ${x[0]==v?'selected':''}>${esc(x[1])}</option>`).join('')}</select>`}
 else if(f.t=='area')h=`<textarea ${a}>${esc(v)}</textarea>`;
 else if(f.t=='check')h=`<label style="display:flex;gap:.5rem;align-items:center;min-height:2.6rem;font-weight:400"><input type="checkbox" ${a} ${v?'checked':''}>${f.cl||'Sí'}</label>`;
 else if(f.t=='checks')h=`<div class="ckl" ${a}>${(typeof f.o=='function'?f.o():f.o).map(o=>`<label style="font-weight:400"><input type="checkbox" name="${f.k}" value="${esc(o)}" ${(v||[]).includes(o)?'checked':''}>${esc(o)}</label>`).join('')}</div>`;
 else h=`<input ${a} value="${esc(v)}" ${f.t=='date'?'placeholder="dd/mm/aaaa" inputmode="numeric"':f.t=='time'?'placeholder="hh:mm" inputmode="numeric"':f.t=='dni'||f.t=='tel'||f.t=='money'||f.t=='num'?'inputmode="decimal"':f.t=='email'?'type="email"':''} autocomplete="off">`;
 return `<div class="fld ${f.w?'w2':''}">${f.t=='checks'||f.t=='check'?'<span>':`<label class="fl" for="${id}">`}${f.l}${f.req?' <span class="req">(obligatorio)</span>':''}${f.t=='checks'||f.t=='check'?'</span>':'</label>'}${h}${f.help?`<div class="fh">${f.help}</div>`:''}${er?`<div class="fe" id="e_${f.k}" role="alert">${I('warn')}${esc(er)}</div>`:''}</div>`}
function readF(fs){const o={};fs.forEach(f=>{const el=$('#f_'+f.k);if(f.t=='check')o[f.k]=el&&el.checked?1:0;else if(f.t=='checks')o[f.k]=$$(`input[name="${f.k}"]:checked`).map(x=>x.value);else o[f.k]=el?el.value.trim():''});return o}
let FS=null;
function abrirForm(ent,id,preset,step){const e=E[ent];const r=id?rec(ent,id):null;
 if(!FS||FS.ent!=ent||FS.id!=id||!FS.keep)FS={ent,id,vals:Object.assign({},e.defaults?e.defaults():{},r?JSON.parse(JSON.stringify(r)):{},preset||{}),errs:{},step:0,keep:1};
 const fs=e.f(FS.vals).filter(f=>!f.view);const steps=e.steps&&!id?e.steps:null;
 const cur=steps?fs.filter(f=>f.step==FS.step):fs;
 const ne=Object.keys(FS.errs).length;
 const body=`${ne?`<div class="esum" role="alert" tabindex="-1" id="esum"><b>${ne==1?'Hay 1 dato por revisar':'Hay '+ne+' datos por revisar'}</b><ul>${Object.entries(FS.errs).map(([k,m])=>`<li><a href="#f_${k}" onclick="event.preventDefault();$('#f_${k}').focus()">${esc((fs.find(f=>f.k==k)||{l:k}).l)}</a>: ${esc(m)}</li>`).join('')}</ul></div>`:''}
 ${e.formInfo?e.formInfo(FS.vals,!!id):''}${id&&e.motivoEdit?`<div class="info">${I('warn')}<span>Esta acta ya está inscrita. Los cambios se registran como <b>rectificación</b> y quedan como nota marginal.</span></div>`:''}
 ${steps&&FS.step==steps.length?`<h3 style="font:400 1.2rem var(--serif);margin:0 0 .6rem">Revise antes de guardar</h3><dl>${fs.filter(f=>!f.hide).map(f=>`<dt>${f.l}</dt><dd>${fv(f,FS.vals[f.k])||'<span class="muted">—</span>'}</dd>`).join('')}</dl>`:`<div class="fg">${cur.map(f=>inp(f,FS.vals[f.k],FS.errs)).join('')}${id&&e.motivoEdit?inp({k:'_motivo',l:'Motivo de la rectificación',req:1,t:'area',w:1},FS.vals._motivo,FS.errs):''}</div>`}`;
 const title=(id?(e.editT||'Editar '+e.s):(e.newT?e.newT(FS.vals):e.nuevo||'Nuevo '+e.s));
 const last=!steps||FS.step==steps.length;
 $('#md').style.width=steps?'50rem':'44rem';
 $('#md').innerHTML=`<div class="drh"><div><h2>${title}</h2><p>${steps?`Paso ${FS.step+1} de ${steps.length+1} · ${FS.step<steps.length?steps[FS.step]:'Revisar'}`:id?esc(e.title(r)):'Complete los datos. Los marcados como obligatorios son necesarios.'}</p></div><button class="btn g" onclick="FS=null;cerrar()">${I('x')}Cerrar</button></div>
 ${steps?`<div class="wz"><div class="wzs">${[...steps,'Revisar'].map((x,i)=>`<div class="${i==FS.step?'on':i<FS.step?'dn':''}"><i>${i<FS.step?'✓':i+1}</i>${x}</div>`).join('')}</div><div class="wzb">${body}</div></div>`:`<div class="drb">${body}</div>`}
 <form class="drf" onsubmit="event.preventDefault();fsub()"><button type="button" class="btn" style="margin-right:auto" ${steps&&FS.step?'':'hidden'} onclick="fback()">${I('left')}Atrás</button><button type="button" class="btn" onclick="FS=null;cerrar()">Cancelar</button><button class="btn p">${last?(id?'Guardar cambios':e.saveL||'Guardar'):'Continuar'}${last?'':I('right')}</button></form>`;
 scr(true);$('#dr').classList.remove('on');$('#md').classList.add('on');
 setTimeout(()=>{const es=$('#esum');if(es)es.focus();else{const f=$('#md .fg input:not([readonly]),#md .fg select,#md .fg textarea');if(f&&!window.KEEP)f.focus()}},30)}
function fcollect(){const e=E[FS.ent];const fs=e.f(FS.vals).filter(f=>!f.view);const steps=e.steps&&!FS.id?e.steps:null;const cur=steps?fs.filter(f=>f.step==FS.step):fs;const extra=FS.id&&e.motivoEdit?[{k:'_motivo',l:'Motivo',req:1}]:[];
 if(!steps||FS.step<steps.length)Object.assign(FS.vals,readF([...cur,...extra]));return {e,fs,steps,cur:[...cur,...extra]}}
function fback(){fcollect();FS.errs={};FS.step--;abrirForm(FS.ent,FS.id)}
function fsub(){const {e,fs,steps,cur}=fcollect();const errs={};
 if(!steps||FS.step<steps.length){cur.forEach(f=>{const m=vfield(f,f.t=='checks'?JSON.stringify(FS.vals[f.k]):FS.vals[f.k]);if(m)errs[f.k]=m});if(e.validate&&!Object.keys(errs).length)Object.assign(errs,Object.fromEntries(Object.entries(e.validate(FS.vals,FS.id)||{}).filter(([k])=>cur.some(f=>f.k==k))))}
 FS.errs=errs;if(Object.keys(errs).length){abrirForm(FS.ent,FS.id);return}
 if(steps&&FS.step<steps.length){FS.step++;abrirForm(FS.ent,FS.id);return}
 const vals=FS.vals,id=FS.id,ent=FS.ent;FS=null;
 if(e.confirmSave&&!id){ask({t:e.confirmSave.t(vals),txt:e.confirmSave.txt(vals),ok:e.confirmSave.ok||'Sí, guardar',onok:()=>saveRec(ent,id,vals,fs),back:()=>{FS={ent,id,vals,errs:{},step:steps?steps.length:0,keep:1};abrirForm(ent,id)}});return}
 saveRec(ent,id,vals,fs)}
function saveRec(ent,id,vals,fs){const e=E[ent],tbl=DB[e.tbl||ent];
 if(id){const r=tbl.find(x=>x.id==id);const ch=fs.filter(f=>!f.hide&&JSON.stringify(r[f.k]??'')!==JSON.stringify(vals[f.k]??'')).map(f=>[f.l,f.t=='checks'?(r[f.k]||[]).join(', '):fvt(f,r[f.k]),f.t=='checks'?(vals[f.k]||[]).join(', '):fvt(f,vals[f.k])]);
  if(!ch.length){cerrar();toast('No hubo cambios que guardar.');return}
  commit(`Cambios guardados en ${e.title(Object.assign({},r,vals))}`,()=>{const mot=vals._motivo;delete vals._motivo;fs.forEach(f=>r[f.k]=vals[f.k]);if(e.onEdit)e.onEdit(r,mot,ch);hist(r,mot?'Rectificó: '+mot:'Editó',ch)},{acc:e.motivoEdit?'Rectificó':'Editó',ent:e.mod||e.p,obj:e.title(r),antes:Object.fromEntries(ch.map(c=>[c[0],c[1]])),despues:Object.fromEntries(ch.map(c=>[c[0],c[2]]))});
  if(DET&&DET.id==id)setTimeout(()=>det(ent,id,DET.tab),10)}
 else{const r=Object.assign({id:nid(ent.slice(0,2)),h:[]},vals);if(e.onCreate)e.onCreate(r);hist(r,e.createAcc||'Creó el registro');
  commit(e.savedMsg?e.savedMsg(r):`${e.s[0].toUpperCase()+e.s.slice(1)} registrad${e.art=='la'?'a':'o'}: ${e.title(r)}`,()=>{tbl.unshift(r);if(e.afterCreate)e.afterCreate(r)},{acc:'Creó',ent:e.mod||e.p,obj:e.title(r),despues:Object.fromEntries(fs.filter(f=>!f.hide&&vals[f.k]).slice(0,6).map(f=>[f.l,fvt(f,vals[f.k])]))});
  if(e.after)setTimeout(()=>e.after(r),60)}}
function fvt(f,v){if(f.t=='ref'){const x=DB[f.ref].find(x=>x.id==v);return x?(f.lab?f.lab(x):x.nombre):''}if(f.t=='money')return v===''?'':money(v);if(f.t=='check')return v?'Sí':'No';return String(v??'')}

/* ---------- confirmaciones ---------- */
let ASK=null;
function ask(o){ASK=o;const er=o.err||'';$('#md2').style.width='30rem';
 $('#md2').innerHTML=`<div class="drh"><div><h2>${o.t}</h2><p>${o.txt||''}</p></div></div><form class="drb" onsubmit="event.preventDefault();askOk()">${o.motivo?`<div class="fld"><span>${o.motivo} <span class="req">(obligatorio)</span></span><textarea id="askm" ${er?'aria-invalid="true"':''}>${esc(o.mv||'')}</textarea>${er?`<div class="fe" role="alert">${I('warn')}${er}</div>`:''}</div>`:''}${o.typed?`<div class="fld"><label class="fl" for="askt">Para confirmar, escriba <b>${o.typed}</b></label><input id="askt" autocomplete="off" ${er?'aria-invalid="true"':''}>${er?`<div class="fe" role="alert">${I('warn')}${er}</div>`:''}</div>`:''}${o.html||''}<p class="sm muted" style="margin:.4rem 0 0">${o.undo===false?'Esta acción no se puede deshacer.':'Después de confirmar podrá deshacerlo durante unos segundos.'}</p></form>
 <div class="drf"><button class="btn" onclick="${o.back?'ASK.back()':'cerrarAsk()'}">${o.back?'Volver a revisar':'Cancelar'}</button><button class="btn p ${o.danger?'dz':''}" style="${o.danger?'background:var(--ac);border-color:var(--ac)':''}" onclick="askOk()">${o.ok||'Confirmar'}</button></div>`;
 scr(true);$('#md2').classList.add('on');setTimeout(()=>{const x=$('#askm')||$('#askt');if(x&&!window.KEEP)x.focus()},30)}
function cerrarAsk(){$('#md2').classList.remove('on');if(!$('#md.on')&&!$('#dr.on'))scr(false)}
function askOk(){const o=ASK;if(o.motivo){const v=$('#askm').value.trim();if(v.length<5){o.err='Escriba el motivo con al menos 5 letras. Quedará en el historial.';o.mv=v;ask(o);return}o.val=v}
 if(o.typed&&$('#askt').value.trim().toUpperCase()!==o.typed){o.err=`Escriba exactamente ${o.typed} para continuar.`;ask(o);return}
 $('#md2').classList.remove('on');o.onok(o.val)}
function borrar(ent,id){const e=E[ent],r=rec(ent,id);ask({t:`¿Eliminar ${e.art||'el'} ${e.s}?`,txt:`Se eliminará «${esc(e.title(r))}». Quedará constancia en Auditoría.`,ok:'Sí, eliminar',danger:1,onok:()=>commit(`Se eliminó ${e.title(r)}`,()=>{const t=DB[e.tbl||ent];t.splice(t.indexOf(t.find(x=>x.id==id)),1)},{acc:'Eliminó',ent:e.mod||e.p,obj:e.title(r)})})}
function anular(ent,id){const e=E[ent],r=rec(ent,id);if(/Anulad/.test(r.estado)){toast('Este registro ya está anulado.');return}ask({t:`¿Anular ${e.art||'el'} ${e.s}?`,txt:`«${esc(e.title(r))}» no se borra: queda marcado como anulado, con el motivo, y no se podrá usar.`,motivo:'Motivo de la anulación',ok:'Sí, anular',danger:1,onok:m=>commit(`Se anuló ${e.title(r)}`,()=>{const a=r.estado;r.estado=e.anulado||'Anulada';r.motivo=m;hist(r,'Anuló: '+m,[['Estado',a,r.estado]]);if(e.onAnular)e.onAnular(r)},{acc:'Anuló',ent:e.mod||e.p,obj:e.title(r),antes:{Estado:r.estado},despues:{Estado:e.anulado||'Anulada',Motivo:m}})})}

/* ---------- impresión y exportación simuladas ---------- */
function paperHead(t,sub){const c=DB.cfg;return `<div class="c" style="letter-spacing:.2em;text-transform:uppercase">${esc(c.diocesis)}</div><div class="c">${esc(c.nombre)} · ${esc(c.dir)}</div><h2 style="font-size:1.25rem">${t}</h2>${sub?`<div class="c">${sub}</div>`:''}<hr style="border:0;border-top:1px solid var(--ln);margin:1rem 0">`}
function seal(){return `<div class="seal" style="${DB.cfg.sello=='Ovalado'?'border-radius:50%/40%;width:6.4rem':''}">${esc(DB.cfg.selloTxt).replace(' · ','<br>')}<br>✝</div>`}
function preview(t,html,o){o=o||{};$('#md').style.width='54rem';$('#md').innerHTML=`<div class="drh"><div><h2>${t}</h2><p>Vista previa de impresión${o.sub?' · '+o.sub:''}</p></div><span class="row" style="margin-left:auto">${o.btns||''}<button class="btn" onclick="exportar('${esc(t)}','PDF',1)">${I('dl')}PDF</button><button class="btn p" onclick="imprimir('${esc(t)}')">${I('print')}Imprimir</button><button class="btn g" onclick="cerrar()">${I('x')}Cerrar</button></span></div><div class="drb" style="background:var(--sb)"><div class="paper">${html}</div></div>`;scr(true);$('#dr').classList.remove('on');$('#md').classList.add('on')}
function imprimir(t){toast(`Se envió «${t}» a la impresora predeterminada (simulado).`)}
function imprimirReg(ent,id){const e=E[ent],r=rec(ent,id);if(e.print)return e.print(r);preview(e.title(r),paperHead('Ficha de '+e.s,esc(e.title(r)))+`<dl style="font-family:var(--sans)">${e.f(r).filter(f=>!f.hide).map(f=>`<dt>${f.l}</dt><dd>${fv(f,r[f.k])||'—'}</dd>`).join('')}</dl><p class="sm" style="font-family:var(--sans);color:var(--t3)">Impreso el ${HOY} a las ${now()} por ${esc(DB.me.nombre)}</p>`)}
function imprimirLista(ent){const e=E[ent];const rows=DB[e.tbl||ent];preview(e.p,paperHead(e.p,`${rows.length} registros · ${HOY}`)+`<table style="font-family:var(--sans);font-size:.85rem"><thead><tr>${e.cols.filter(c=>!c.ns||c.k).map(c=>`<th>${c.l}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,25).map(r=>`<tr>${e.cols.filter(c=>!c.ns||c.k).map(c=>`<td style="white-space:normal">${c.f?c.f(r):esc(r[c.k])}</td>`).join('')}</tr>`).join('')}</tbody></table>`)}
function exportar(nombre,fmt,direct){const go=f=>{$('#md2').innerHTML=`<div class="drh"><div><h2>Preparando archivo…</h2><p>${esc(nombre)} · ${f}</p></div></div><div class="drb"><div class="bar" style="width:100%"><i id="xpb" style="width:5%;transition:width .9s"></i></div><p class="sm muted">Esto puede tardar unos segundos.</p></div>`;$('#md2').classList.add('on');scr(true);setTimeout(()=>{const b=$('#xpb');if(b)b.style.width='100%'},50);setTimeout(()=>{$('#md2').classList.remove('on');if(!$('#md.on')&&!$('#dr.on'))scr(false);const fn=nombre.replace(/[^\wáéíóúñ ()·-]/gi,'').trim()+'.'+(f=='Excel'?'xlsx':f.toLowerCase());DB.exports.unshift({id:nid('ex'),nombre:fn,fecha:HOY+' '+now(),u:DB.me.nombre});save();toast(`Archivo listo: «${fn}» (simulado, no se descargó nada).`)},window.KEEP?60:1100)};
 if(direct)return go(fmt);
 ask({t:'Exportar',txt:esc(nombre),html:`<div class="fld"><span>Formato</span><div class="seg" role="radiogroup">${['Excel','PDF','CSV'].map((f,i)=>`<button type="button" class="${i?'':'on'}" onclick="$$('#md2 .seg button').forEach(b=>b.classList.remove('on'));this.classList.add('on')">${f}</button>`).join('')}</div></div><label class="ckl"><label style="font-weight:400"><input type="checkbox" checked>Incluir solo los registros filtrados</label></label>`,ok:'Exportar',undo:false,onok:()=>go($('#md2 .seg .on')?.textContent||'Excel')})}

/* ---------- capa general ---------- */
function scr(on){$('#scr').classList.toggle('on',on)}
function cerrar(){['#dr','#md','#md2','#pal','aside'].forEach(s=>$(s).classList.remove('on'));$$('.dd.on,.zm.on').forEach(x=>x.classList.remove('on'));scr(false);DET=null}
let tt;function toast(m,u,extra){const t=$('#toast');t.innerHTML=`${I('check')}<span>${esc(m)}</span>${extra||''}${u?`<button class="btn" onclick="undo()">Deshacer</button>`:''}`;t.classList.add('on');clearTimeout(tt);if(!window.KEEP)tt=setTimeout(()=>t.classList.remove('on'),9000)}
